<section class="ac-card"><div class="ac-head"><div><h2>Repeated-return review</h2><p>Three or more requests in 30 days create a review flag. No return is automatically rejected or customer blocked.</p></div><button class="ac-btn" id="ar-refresh" type="button"><i class="fa-solid fa-rotate"></i> Refresh</button></div><div class="ac-body"><p id="ar-status" role="status">Loading review flags…</p><div class="ac-table-wrap"><table class="ac-table"><thead><tr><th>Customer</th><th>Scope</th><th>Requests</th><th>Flagged</th><th>Vendor note</th><th>Admin review</th><th>Action</th></tr></thead><tbody id="ar-flags"></tbody></table></div></div></section>
<dialog class="ac-dialog" id="ar-dialog"><div class="ac-dialog-head"><h2>Review return pattern</h2><button class="ac-btn small" type="button" id="ar-close">Close</button></div><form class="ac-body" id="ar-form"><p id="ar-customer"></p><label class="ac-field">Status<select class="ac-select" name="status" required><option value="open">Open</option><option value="monitoring">Monitoring</option><option value="cleared">Cleared</option></select></label><label class="ac-field mt-2">Reason for decision<textarea class="ac-textarea" name="note" minlength="20" maxlength="2000" required placeholder="Explain the evidence reviewed and why this status is appropriate."></textarea></label><p>This review does not alter return eligibility or customer account access.</p><div class="ac-form-actions"><button class="ac-btn primary" type="submit">Save audited review</button></div></form></dialog>
